function sha256(buffer) { return crypto.createHash('sha256').update(buffer).digest('hex'); }
function readHash(file) { return fs.existsSync(file) ? sha256(fs.readFileSync(file)) : null; }
function stamp() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
}
function fail(message, code = 1) { console.error(`\n[V23] ERRO: ${message}`); process.exit(code); }
function ensureProjectRoot() {
  const mustExist = ['settings.gradle.kts','app/src/main/java/br/com/usinagemmaster','firebase.json'];
  const missing = mustExist.filter((p) => !fs.existsSync(path.join(root,p)));
  if (missing.length) fail(`Execute este .mjs na raiz do projeto UsinagemMaster. Não encontrei: ${missing.join(', ')}`);
}
function inspect() {
  return manifest.map((item) => {
    const target = path.join(root, ...item.path.split('/'));
    const current = readHash(target);
    let status;
    if (current === item.finalSha256) status = 'APPLIED';
    else if (item.expectedSha256 === null && current === null) status = 'READY_NEW';
    else if (item.expectedSha256 !== null && current === item.expectedSha256) status = 'READY_MOD';
    else status = 'CONFLICT';
    return {...item,target,current,status};
  });
}
function printInspection(rows) {
  const counts=rows.reduce((a,r)=>((a[r.status]=(a[r.status]||0)+1),a),{});
  console.log(`\n[V23] ${PATCH_NAME}`);
  console.log(`[V23] Projeto: ${root}`);
  console.log(`[V23] Arquivos: ${rows.length} | alterar: ${counts.READY_MOD||0} | novos: ${counts.READY_NEW||0} | aplicados: ${counts.APPLIED||0} | conflitos: ${counts.CONFLICT||0}`);
  const conflicts=rows.filter(r=>r.status==='CONFLICT');
  if (conflicts.length) {
    console.log('\n[V23] Arquivos diferentes da V22 esperada:');
    for (const r of conflicts) console.log(`  - ${r.path}`);
  }
}
function backupRows(rows, backupRoot) {
  for (const r of rows) {
    if (r.status==='APPLIED' || !fs.existsSync(r.target)) continue;
    const dest=path.join(backupRoot,...r.path.split('/'));
    fs.mkdirSync(path.dirname(dest),{recursive:true});
    fs.copyFileSync(r.target,dest);
  }
}
function applyRows(rows, backupRoot) {
  const changed=[];
  try {
    for (const r of rows) {
      if (r.status==='APPLIED') continue;
      fs.mkdirSync(path.dirname(r.target),{recursive:true});
      fs.writeFileSync(r.target,Buffer.from(r.contentBase64,'base64'));
      if (readHash(r.target)!==r.finalSha256) throw new Error(`SHA-256 inválido em ${r.path}`);
      changed.push(r);
      console.log(`[V23] OK: ${r.path}`);
    }
  } catch (err) {
    console.error(`\n[V23] Falha durante aplicação: ${err?.message||err}`);
    console.error('[V23] Executando rollback...');
    for (const r of changed.reverse()) {
      const backed=path.join(backupRoot,...r.path.split('/'));
      try {
        if (fs.existsSync(backed)) fs.copyFileSync(backed,r.target);
        else if (r.expectedSha256===null) fs.rmSync(r.target,{force:true});
      } catch (rollbackErr) {
        console.error(`[V23] AVISO rollback manual em ${r.path}: ${rollbackErr?.message||rollbackErr}`);
      }
    }
    throw err;
  }
}
function verifyFinal() {
  const bad=[];
  for (const item of manifest) {
    const target=path.join(root,...item.path.split('/'));
    if (readHash(target)!==item.finalSha256) bad.push(item.path);
  }
  if (bad.length) fail(`Verificação final falhou em: ${bad.join(', ')}`);
  console.log(`[V23] Verificação SHA-256: ${manifest.length}/${manifest.length} arquivos corretos.`);
}
function buildProject() {
  const isWin=process.platform==='win32';
  const wrapper=path.join(root,isWin?'gradlew.bat':'gradlew');
  if (!fs.existsSync(wrapper)) { console.warn('[V23] AVISO: gradle wrapper não encontrado.'); return; }
  console.log('\n[V23] Compilando Kotlin do app...');
  const cmd=isWin?wrapper:'./gradlew';
  const result=spawnSync(cmd,[':app:compileDebugKotlin','--stacktrace'],{cwd:root,stdio:'inherit',shell:isWin});
  if (result.error) fail(`Não foi possível iniciar o Gradle: ${result.error.message}`);
  if (result.status!==0) fail(`Patch aplicado, mas o Gradle retornou código ${result.status}. O backup foi preservado.`);
  console.log('[V23] BUILD OK.');
}

ensureProjectRoot();
