printInspection(rows);
const conflicts=rows.filter(r=>r.status==='CONFLICT');
if (checkOnly) {
  if (conflicts.length && !force) process.exitCode=2;
  else console.log('[V23] CHECK OK.');
  process.exit();
}
if (conflicts.length && !force) {
  console.error('\n[V23] Segurança: este patch espera a V22 já aplicada e não sobrescreveu seus arquivos divergentes.');
  console.error('[V23] Use --force somente depois de revisar os conflitos.');
  process.exit(2);
}
const toWrite=rows.filter(r=>r.status!=='APPLIED');
if (!toWrite.length) {
  console.log('\n[V23] Cloud Save V23 já está aplicado.');
  verifyFinal();
  if (runBuild) buildProject();
  process.exit();
}
const backupRoot=path.join(root,`backup-usinagem-v23-cloud-save-${stamp()}`);
fs.mkdirSync(backupRoot,{recursive:true});
backupRows(toWrite,backupRoot);
console.log(`\n[V23] Backup local: ${backupRoot}`);
try { applyRows(toWrite,backupRoot); verifyFinal(); } catch (err) { fail(err?.message||String(err)); }
console.log('\n[V23] APLICAÇÃO CONCLUÍDA.');
console.log('[V23] Cloud Save: Room + DataStores + personagem + gacha + skills + histórico + fábrica são salvos por UID Google.');
console.log('[V23] Novo aparelho com a mesma conta restaura o slot da nuvem automaticamente.');
console.log('[V23] IMPORTANTE: publique firestore.rules no Firebase antes de testar o backup.');
console.log('[V23] Com Firebase CLI: firebase deploy --only firestore:rules');
if (runBuild) buildProject();
